"vaccines":[{"name":"vaccine as written, e.g. DTaP, HepB, MMR, 百白破","date":"YYYY-MM-DD the dose was given, or null","dose":1|2|3|4|5|"booster"|null,"site":"left thigh|right thigh|left arm|right arm|oral|null"}],
